L2_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Talk_KOREA = "실험 기지로 돌아갈 줄 알았는데- 정말 그림자를 토벌하러 갈 셈인가요?"
L2_1.m_fTalkTime = 0.03
L2_1.m_Talk_JPN = "実験基地に帰るのかと思いましたが……本当にシャドウ討伐に向かうつもりですか？"
L2_1.m_Talk_ENG = "I thought you would go back to the testing base. Are you going to eliminate the Shadow?"
L2_1.m_Talk_TWN = "我以為你會回到實驗基地。真的要去討伐暗影嗎？"
L2_1.m_Talk_SCN = "我以为你会回到实验基地。真的要去讨伐暗影吗？"
L2_1.m_Talk_DEU = "I thought you would go back to the testing base. Are you going to eliminate the Shadow?"
L2_1.m_Talk_FRA = "I thought you would go back to the testing base. Are you going to eliminate the Shadow?"
L3_1 = {}
L3_1.m_CutScenKey_Talk = "EP12_ACT4_INTERLUDE18@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 575
L3_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "COMMANDER_UNION_NULL_NULL"
L3_1.m_Pos = "C"
L3_1.m_Talk_KOREA = "잡아야지. 그림자는 한 번 놓치면 기약이 없으니까."
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "そうだ。シャドウを1度逃がしたら、次のチャンスはいつになるかわからない。"
L3_1.m_Talk_ENG = "I must do now, as there is no guarantee of another chance to defeat a Shadow."
L3_1.m_Talk_TWN = "是必須。暗影一旦錯過就不知道什麼時候會再出現。"
L3_1.m_Talk_SCN = "是必须。暗影一旦错过就不知道什么时候再出现了。"
L3_1.m_Talk_DEU = "I must do now, as there is no guarantee of another chance to defeat a Shadow."
L3_1.m_Talk_FRA = "I must do now, as there is no guarantee of another chance to defeat a Shadow."
