L5_1 = {}
L5_1.m_CutScenKey_Talk = "EP12_ACT4_INTERLUDE18@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 575
L5_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Talk_KOREA = "발키리를 없애는 게 당신의 가장 큰 소망인 줄 알았는데요."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "ヴァルキリーを始末することこそ、あなたの一番の望みだと思っていました。"
L5_1.m_Talk_ENG = "I thought getting rid of the Valkyrie was your biggest wish."
L5_1.m_Talk_TWN = "我以為消滅女武神是你最大的願望。"
L5_1.m_Talk_SCN = "我还以为消灭女武神是你最大的愿望呢。"
L5_1.m_Talk_DEU = "I thought getting rid of the Valkyrie was your biggest wish."
L5_1.m_Talk_FRA = "I thought getting rid of the Valkyrie was your biggest wish."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "EP12_ACT4_INTERLUDE18@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 575
L6_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "COMMANDER_UNION_NULL_NULL"
L6_1.m_Pos = "C"
L6_1.m_Talk_KOREA = "죽이지 못해도 힘을 절반으로 만드는 덴 성공했어."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "殺すことはできなかったが、力を半分にすることはできた。"
L6_1.m_Talk_ENG = "Although she's not dead, I did succeed in halving her strength."
L6_1.m_Talk_TWN = "雖然沒能殺死她，但也成功削弱了她一半的力量。"
L6_1.m_Talk_SCN = "虽然没能杀死她，但也成功削弱了她一半的力量。"
L6_1.m_Talk_DEU = "Although she's not dead, I did succeed in halving her strength."
L6_1.m_Talk_FRA = "Although she's not dead, I did succeed in halving her strength."
L7_1 = {}
L7_1.m_CutScenKey_Talk = "EP12_ACT4_INTERLUDE18@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 575
L7_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L7_1.m_bWaitClick = true
