L7_1.m_Face = "UNIT_IDLE"
L7_1.m_CharStrID = "COMMANDER_UNION_NULL_NULL"
L7_1.m_Pos = "C"
L7_1.m_Talk_KOREA = "너도 그걸 원했잖아? 삼하인."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "君もそれを望んでいたのでは？　サウィン。"
L7_1.m_Talk_ENG = "And didn't you want that too, Samhain?"
L7_1.m_Talk_TWN = "這不也是你想要的嗎？薩溫。"
L7_1.m_Talk_SCN = "你不也想要这个吗？萨温。"
