L9_1 = {}
L9_1.m_CutScenKey_Talk = "EP12_ACT4_INTERLUDE18@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 575
L9_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Talk_KOREA = "확실히… 계약대로 발키리의 힘을 약화시켰으니- 더 이상 제가 참견할 일은 아니군요."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "そうですね……契約どおりヴァルキリーの力を弱らせた。これ以上私が口を出す必要はありません。"
L9_1.m_Talk_ENG = "Yes... You did weaken her powers as you promised... So, it is not my place to meddle anymore."
L9_1.m_Talk_TWN = "是的……你按照契約削弱了女武神的力量……接下來就不是我該插手的事了。"
L9_1.m_Talk_SCN = "是的……你按照契约削弱了女武神的力量……接下来就不是我该插手的事了。"
L9_1.m_Talk_DEU = "Yes... You did weaken her powers as you promised... So, it is not my place to meddle anymore."
L9_1.m_Talk_FRA = "Yes... You did weaken her powers as you promised... So, it is not my place to meddle anymore."
L10_1 = {}
L10_1.m_CutScenKey_Talk = "EP12_ACT4_INTERLUDE18@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 575
L10_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Talk_KOREA = "하지만, 당신이 감정을 앞세워 판단을 바꾸는 건 드문 일이에요."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "ですが、あなたが感情を優先して判断を変えるとは珍しい。"
L10_1.m_Talk_ENG = "However, it is rare of you to change your decision based on your emotions."
L10_1.m_Talk_TWN = "但你很少會讓感情左右你的判斷。"
L10_1.m_Talk_SCN = "但是，你因为情感而改变判断是很少见的事。"
L10_1.m_Talk_DEU = "However, it is rare of you to change your decision based on your emotions."
L10_1.m_Talk_FRA = "However, it is rare of you to change your decision based on your emotions."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "EP12_ACT4_INTERLUDE18@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 575
L11_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "COMMANDER_UNION_NULL_NULL"
L11_1.m_Pos = "C"
L11_1.m_Talk_KOREA = "맞아. 네 경고처럼 내 인간성이 계획을 그르친 걸지도 모르지."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "そうだ。君が警告したとおり、私の中の人間性に計画を邪魔されたのかもしれない。"
L11_1.m_Talk_ENG = "You're right. Perhaps my humanity may have blundered the plan like you warned."
L11_1.m_Talk_TWN = "嗯。就像你警告的那樣，我的人性可能破壞了計畫。"
L11_1.m_Talk_SCN = "没错。正如你警告的那样，我的人性可能破坏了这个计划。"
L11_1.m_Talk_DEU = "You're right. Perhaps my humanity may have blundered the plan like you warned."
L11_1.m_Talk_FRA = "You're right. Perhaps my humanity may have blundered the plan like you warned."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "EP12_ACT4_INTERLUDE18@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 575
L12_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "COMMANDER_UNION_NULL_NULL"
L12_1.m_Pos = "C"
L12_1.m_Talk_KOREA = "패러독스를 우물에 혼자 빠뜨리면, 발키리의 운명이 그자를 살리기 위해 권능을 쓸 줄 알았는데…"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "パラドックスを1人で井戸に入らせれば、ヴァルキリーの運命が彼女を助けるために権能を使うだろうと思ったが……"
L12_1.m_Talk_ENG = "I thought Valkyrie's fate would use her power to save Paradox if she fell into the Well by herself..."
L12_1.m_Talk_TWN = "如果把悖論單獨扔進井裡，我推斷女武神會用她的權能去救她……"
L12_1.m_Talk_SCN = "如果把悖论单独扔进井里，我推断女武神会用她的权能去救她……"
L12_1.m_Talk_DEU = "I thought Valkyrie's fate would use her power to save Paradox if she fell into the Well by herself..."
L12_1.m_Talk_FRA = "I thought Valkyrie's fate would use her power to save Paradox if she fell into the Well by herself..."
L13_1 = {}
L13_1.m_CutScenKey_Talk = "EP12_ACT4_INTERLUDE18@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 575
L13_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_DESPAIR"
L13_1.m_CharStrID = "COMMANDER_UNION_NULL_NULL"
L13_1.m_Pos = "C"
L13_1.m_Talk_KOREA = "그 영향이 뜻밖의 인물을 데려올 줄은 몰랐어."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "その影響を受けて、思いがけない人物を連れてくる結果は想定していなかった。"
L13_1.m_Talk_ENG = "But I didn't expect it would result in bringing back an unexpected person."
L13_1.m_Talk_TWN = "但那個決定竟然會帶來意想不到的人物。"
L13_1.m_Talk_SCN = "但那个决定竟然会带来意想不到的人物。"
L13_1.m_Talk_DEU = "But I didn't expect it would result in bringing back an unexpected person."
L13_1.m_Talk_FRA = "But I didn't expect it would result in bringing back an unexpected person."
