L15_1 = {}
L15_1.m_CutScenKey_Talk = "EP12_ACT4_INTERLUDE18@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 575
L15_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Talk_KOREA = "흐음- 당신의 마음을 건드린 게 그 아이였군요?"
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "ふむ……ではあの子があなたの心を動かしたのですね。"
L15_1.m_Talk_ENG = "Hmm... Was it that child who touched your heart?"
L15_1.m_Talk_TWN = "嗯……是那個孩子觸動了你的心嗎？"
L15_1.m_Talk_SCN = "嗯……是那个孩子触动了你的心吗？"
L15_1.m_Talk_DEU = "Hmm... Was it that child who touched your heart?"
L15_1.m_Talk_FRA = "Hmm... Was it that child who touched your heart?"
L16_1 = {}
L16_1.m_CutScenKey_Talk = "EP12_ACT4_INTERLUDE18@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 575
L16_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Talk_KOREA = "<color=#ffd34c>파블린</color>이란 이름은… 당신이 의무관 시절 살리지 못한 임산부이잖습니까?"
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "<color=#ffd34c>パブリン</color>という名前は……あなたが医務官だった頃、助けられなかった妊婦でしょう？"
L16_1.m_Talk_ENG = "<color=#ffd34c>Pavlin</color>... Wasn't that the name of the pregnant women you could not save when you were a medical officer?"
L16_1.m_Talk_TWN = "那個叫<color=#ffd34c>帕芙琳</color>的女人……不就是你還是醫務官時沒能救活的那個孕婦嗎？"
L16_1.m_Talk_SCN = "那个叫<color=#ffd34c>帕芙琳</color>的女人……不就是你还是医务官时没能救活的那个孕妇吗？"
L16_1.m_Talk_DEU = "<color=#ffd34c>Pavlin</color>... Wasn't that the name of the pregnant women you could not save when you were a medical officer?"
L16_1.m_Talk_FRA = "<color=#ffd34c>Pavlin</color>... Wasn't that the name of the pregnant women you could not save when you were a medical officer?"
L17_1 = {}
L17_1.m_CutScenKey_Talk = "EP12_ACT4_INTERLUDE18@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 575
L17_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_DESPAIR"
L17_1.m_CharStrID = "COMMANDER_UNION_NULL_NULL"
L17_1.m_Pos = "C"
L17_1.m_Talk_KOREA = "그러게. 운명이란 건 참 얄궂네."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "そうだな。運命とは皮肉なものだ。"
L17_1.m_Talk_ENG = "Yeah. Fate can be cruel at times."
L17_1.m_Talk_TWN = "是啊，命運真是太討厭了。"
L17_1.m_Talk_SCN = "是啊，命运真是太讨厌了。"
L17_1.m_Talk_DEU = "Yeah. Fate can be cruel at times."
L17_1.m_Talk_FRA = "Yeah. Fate can be cruel at times."
L18_1 = {}
L18_1.m_CutScenKey_Talk = "EP12_ACT4_INTERLUDE18@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 575
L18_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "COMMANDER_UNION_NULL_NULL"
L18_1.m_Pos = "C"
L18_1.m_Talk_KOREA = "이번 세계에서조차, 그녀를 구하지 못했는데…"
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "今回の世界ですら、彼女を救えなかったのに……"
L18_1.m_Talk_ENG = "Even in this world, I wasn't able to save her..."
L18_1.m_Talk_TWN = "即使在這個世界，我也沒能拯救她……"
L18_1.m_Talk_SCN = "即使在这个世界，我也没能拯救她……"
L18_1.m_Talk_DEU = "Even in this world, I wasn't able to save her..."
L18_1.m_Talk_FRA = "Even in this world, I wasn't able to save her..."
