L19_1.m_CharStrID = "COMMANDER_UNION_NULL_NULL"
L19_1.m_Pos = "C"
L19_1.m_Talk_KOREA = "오늘 그곳에서 그녀의 아이를 만나게 될 줄이야."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "今日あの場所で彼女の子どもに出会うとは。"
L19_1.m_Talk_ENG = "Who would've known I'd meet her daughter here today."
L19_1.m_Talk_TWN = "誰又會料到會在那遇到她的孩子呢？"
L19_1.m_Talk_SCN = "谁又会料到会在那儿遇到了她的孩子呢？"
