L21_1.m_CutScenKey_Talk = "EP12_ACT4_INTERLUDE18@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 575
L21_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Talk_KOREA = "그 아이가 당신에게 그렇게 각별하다면, 어째서 데려오지 않았죠?"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "あなたにとってあの子がそれほどに特別な存在なら、なぜ連れて来なかったのですか？"
L21_1.m_Talk_ENG = "If that child means so much to you, then why didn't to take her with you?"
L21_1.m_Talk_TWN = "如果那個孩子對你如此重要，為什麼不把她留在身邊……"
L21_1.m_Talk_SCN = "如果那个孩子对你如此重要，为什么不把她留在身边……"
L21_1.m_Talk_DEU = "If that child means so much to you, then why didn't to take her with you?"
L21_1.m_Talk_FRA = "If that child means so much to you, then why didn't to take her with you?"
L22_1 = {}
L22_1.m_CutScenKey_Talk = "EP12_ACT4_INTERLUDE18@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 575
L22_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_HATE"
L22_1.m_CharStrID = "COMMANDER_UNION_NULL_NULL"
L22_1.m_Pos = "C"
L22_1.m_Talk_KOREA = "난 내 곁에 소중한 걸 두지 않아."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "私は大切なものを側に置いたりしない。"
L22_1.m_Talk_ENG = "I don't keep things I cherish next to me."
L22_1.m_Talk_TWN = "我不會把珍貴的東西留在身邊。"
L22_1.m_Talk_SCN = "我不会把珍贵的东西留在身边。"
L22_1.m_Talk_DEU = "I don't keep things I cherish next to me."
L22_1.m_Talk_FRA = "I don't keep things I cherish next to me."
L23_1 = {}
