L23_1.m_Talk_KOREA = "필요한 것만 두고, 이용할 뿐이지."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "必要なものだけを側に置き、利用するだけだ。"
L23_1.m_Talk_ENG = "Only necessities that I use."
L23_1.m_Talk_TWN = "只留下需要的、能利用的而已。"
L23_1.m_Talk_SCN = "只留下需要的、能利用的而已。"
