L26_1.m_CutScenID = 575
L26_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Talk_KOREA = "곧 그들 앞에 나타날 <color=#ffd34c>불청객</color>과 엮이게 되면, 그 소중한 아이도 살아남기 힘들 텐데요."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "まもなく彼らの前に現れる<color=#ffd34c>招かれざる客</color>と接点ができてしまったら、あの子も生き残れないはずです。"
L26_1.m_Talk_ENG = "Soon, when they encounter the <color=#ffd34c>uninvited</color>, and the child's chances of survival will be unlikely."
L26_1.m_Talk_TWN = "如果與即將出現在他們面前的<color=#ffd34c>不速之客</color>糾纏在一起，那個孩子也很難生存下來喔？"
L26_1.m_Talk_SCN = "如果与即将出现在他们面前的<color=#ffd34c>不速之客</color>纠缠在一起，那个孩子也很难生存下来哦？"
L26_1.m_Talk_DEU = "Soon, when they encounter the <color=#ffd34c>uninvited</color>, and the child's chances of survival will be unlikely."
L26_1.m_Talk_FRA = "Soon, when they encounter the <color=#ffd34c>uninvited</color>, and the child's chances of survival will be unlikely."
