L28_1.m_CharStrID = "COMMANDER_UNION_NULL_NULL"
L28_1.m_Pos = "C"
L28_1.m_Talk_KOREA = "권총 한 발에 죽을 만큼 연약한 인간이지만, 그 운명은 마왕보다 질기거든."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "銃弾1発で死ぬほど非力な人間ではあるが、その運命は魔王よりもしぶとい。"
L28_1.m_Talk_ENG = "He might be a weak human who can be killed by a single bullet, but his fate is tougher than a Demon Lord's."
L28_1.m_Talk_TWN = "雖然是脆弱到一顆子彈就能殺死的人類，但他的命運比魔王還要頑強。"
L28_1.m_Talk_SCN = "虽然是脆弱到一颗子弹就能杀死的人类，但他的命运比魔王还要顽强。"
L28_1.m_Talk_DEU = "He might be a weak human who can be killed by a single bullet, but his fate is tougher than a Demon Lord's."
L28_1.m_Talk_FRA = "He might be a weak human who can be killed by a single bullet, but his fate is tougher than a Demon Lord's."
