L13_1 = "당신 같은 분이… 어째서 우릴 찾아온 겁니까?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "あなたのようなお方がなぜ……ここになんの用です？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Why has someone like you... come to see us?"
