L13_1.m_CharStrID = L14_1
L14_1 = "R"
L13_1.m_Pos = L14_1
L14_1 = "저희 주인님께선 시련을 하사하고 관망하길 즐기시는 분이죠."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "私のご主人様は、試練を授け、その様子を観望することを好まれています。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "My master is someone who enjoys giving trials and observing them."
L13_1.m_Talk_ENG = L14_1
L14_1 = "我的主人喜歡給予對手試煉並觀望。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "我们的主人喜欢给予对手试炼并观望。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "My master is someone who enjoys giving trials and observing them."
L13_1.m_Talk_DEU = L14_1
L14_1 = "My master is someone who enjoys giving trials and observing them."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EP12_ACT4_INTERLUDE18@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 575
L14_1.m_CutScenStrID = "EP12_ACT4_INTERLUDE18"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "DOMA_FALLEN_NULL_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "R"
L14_1.m_Pos = L15_1
L15_1 = "숙적이 힘을 되찾고자 함을 아시고, 이 하찮은 시종을 훼방꾼으로 보내셨답니다."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "宿敵が力を取り戻そうとしていることに気づき、このしがない僕に邪魔者という任務を与えたのです。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Learning that her archenemy has set out to regain her power, she has sent her lowly servant as a saboteur."
L14_1.m_Talk_ENG = L15_1
L15_1 = "她的宿敵想要恢復力量，便派遣了我這個卑微的僕人前來阻撓。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "她的宿敌想要恢复力量，便派遣了我这个卑微的侍从前来阻挠。"
L14_1.m_Talk_SCN = L15_1
