L38_1 = "USER_ADMIN_NULL_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "자네 주인은 강자와 싸우고 싶어하는 줄 알았는데, 그 기회를 저버리고 훼방을 놓으러 온 건가?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "君の主は強者と戦いたいのだと思っていたが、絶好のチャンスを捨てて私たちを邪魔しに来たのか？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I thought your master only wanted to fight strong foes. Yet, why did she throw away that opportunity to only send over a saboteur?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "我以為你的主人渴望與強者一戰，結果卻放棄了這個機會，派你來這裡搗亂嗎？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "我以为你的主人渴望与强者一战，结果却放弃了这个机会，派你来这里捣乱吗？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "I thought your master only wanted to fight strong foes. Yet, why did she throw away that opportunity to only send over a saboteur?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "I thought your master only wanted to fight strong foes. Yet, why did she throw away that opportunity to only send over a saboteur?"
