L12_1 = "흥미롭군요. 약점을 노리는 순간 그림자공간으로 숨어들어 반격하다니."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "興味深い。弱点を狙った瞬間、シャドウの空間に潜んで反撃してくるとは。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Interesting. The moment I target your weak spot, you sneak into the shadow space and counterattacks."
L11_1.m_Talk_ENG = L12_1
L12_1 = "有趣。趁著對方露出破綻的瞬間，遁入暗影空間進行反擊。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "有趣。趁着对方露出破绽的瞬间，遁入暗影空间进行反击。"
