L37_1 = "R"
L36_1.m_Pos = L37_1
L37_1 = "그림자는 본능적으로 인간과 달리 눈과 귀 대신 그림자만의 감각을 이용하곤 하죠."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "シャドウは人間と違い、本能的に目と耳の代わりにシャドウならではの感覚に頼る傾向があります。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Shadows instinctively use their own sense instead of relying on their eyes and ears like humans."
L36_1.m_Talk_ENG = L37_1
L37_1 = "就像人類會本能地使用眼睛和耳朵一樣，暗影也會本能地使用你獨有的感官。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "就像人类会本能地使用眼睛和耳朵一样，暗影也会本能地使用你独有的感官。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Shadows instinctively use their own sense instead of relying on their eyes and ears like humans."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Shadows instinctively use their own sense instead of relying on their eyes and ears like humans."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP12_ACT4_INTERLUDE18@237#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 237
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 575
