L38_1 = "DOMA_FALLEN_NULL_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "R"
L37_1.m_Pos = L38_1
L38_1 = "당신도 인간 흉내를 내지만, 결국 본질은 데모고르곤이란 거네요."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "あなたも人間の真似をしているだけで、本質はデモゴルゴンというわけですね。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "You may act like a human, but at your core, you are a Demogorgon."
L37_1.m_Talk_ENG = L38_1
L38_1 = "你雖然在模仿人類，但本質上還是個魔神啊。"
